create or replace view IDQ_PRODUCTION.EKS_CALCULATION.SVMARA_EKS_ITEM_WITH_MEASURE_GT_CM_SEL(
	NEGOTIATINGCOUNTRY,
	BUYERSHORTSIGN,
	BUYERFIRSTNAME,
	BUYERLASTNAME,
	ZMATKL,
	ARTICLEFAMILY,
	ITEMID,
	ITEMNO,
	ARTICLETYPE,
	DESCRIPTION,
	CASEDEPTH,
	CASEWIDTH,
	CASEHEIGHT,
	UNITDESCRIPTION,
	VOLUME,
	CASESIZE,
	DECIMALCASESIZE,
	LISTINGOVERVIEWID,
	SUPPLIERNO,
	SUPPLIERDESCRIPTION,
	RECEIVINGCOUNTRY,
	ZRELEVANTMDM,
	ZSOURCE,
	ZACTIVE
) as
(SELECT DISTINCT EKS_CALCULATION.stMARA_EKS_ITEM.zNegotiatingCountry AS NegotiatingCountry, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerSHORTSIGN, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerFirstName, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerLastName, EKS_CALCULATION.stMARA_EKS_ITEM.zMATKL, EKS_CALCULATION.stMARA_EKS_ITEM.ArticleFamily, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO, EKS_CALCULATION.stMARA_EKS_ITEM.zArticleType AS ArticleType, EKS_CALCULATION.stMARA_EKS_ITEM.DESCRIPTION_INT AS Description, EKS.ITEMDIMENSION.CASEDEPTH, EKS.ITEMDIMENSION.CASEWIDTH, EKS.ITEMDIMENSION.CASEHEIGHT, EKS.TRANSLATION_INT_UNIT.DESCRIPTION AS UnitDescription, EKS_CALCULATION.svMARA_EKS_ITEM_Messures_Diff_BETW_Articles010.Volume, eks.casesize, eks.DecimalCaseSize, eks.LISTINGOVERVIEWID, EKS.SUPPLIER.INTSUPPLIERNO AS SUPPLIERNO, EKS.SUPPLIER.DESCRIPTION AS SUPPLIERDESCRIPTION, eks.ReceivingCountry, eks.zRelevantMDM, EKS_CALCULATION.stMARA_EKS_ITEM.zSource, EKS_CALCULATION.stMARA_EKS_ITEM.zActive
FROM     EKS_CALCULATION.stMARA_EKS_ITEM INNER JOIN
                      (SELECT DISTINCT 'EA' AS Articletype, itemid, ITEMNO, LISTINGOVERVIEWID, casesize, ReceivingCountry, SUPPLIERNO, CONTRACTLINKID, CONTRACTPRICEVALIDITYID, DecimalCaseSize, CONTRACTPRICERELID, zIsWAWIRelevant AS zRelevantMDM
                       FROM      EKS_CALCULATION.xtEKS_BASICINFO_RecCountry
                       WHERE   (SK_ITEMNO IS NULL)
                       UNION ALL
                       SELECT DISTINCT 'SK' AS Articletype, SK_ITEMID AS ITEMID, SK_ITEMNO AS itemno, LISTINGOVERVIEWID, casesize, ReceivingCountry, SUPPLIERNO, CONTRACTLINKID, CONTRACTPRICEVALIDITYID, DecimalCaseSize, CONTRACTPRICERELID, zIsWAWIRelevant AS zRelevantMDM
                       FROM     EKS_CALCULATION.xtEKS_BASICINFO_RecCountry
                       WHERE  (SK_ITEMID IS NOT NULL)) AS eks ON eks.itemid = EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID INNER JOIN
EKS_CALCULATION.svMARA_EKS_ITEM_Messures_Diff_BETW_Articles010 ON eks.itemid = EKS_CALCULATION.svMARA_EKS_ITEM_Messures_Diff_BETW_Articles010.ITEMID AND eks.LISTINGOVERVIEWID = EKS_CALCULATION.svMARA_EKS_ITEM_Messures_Diff_BETW_Articles010.LISTINGOVERVIEWID AND eks.casesize = EKS_CALCULATION.svMARA_EKS_ITEM_Messures_Diff_BETW_Articles010.casesize AND eks.ReceivingCountry = EKS_CALCULATION.svMARA_EKS_ITEM_Messures_Diff_BETW_Articles010.receivingcountry INNER JOIN
EKS.CONTRACTPRICEVALIDITY ON EKS.CONTRACTPRICEVALIDITY.CONTRACTPRICEVALIDITYID = eks.CONTRACTPRICEVALIDITYID INNER JOIN
EKS.ITEMDIMENSION  ON eks.CONTRACTPRICEVALIDITYID = EKS.ITEMDIMENSION.CONTRACTPRICEVALIDITYID AND EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID = EKS.ITEMDIMENSION.ITEMID INNER JOIN
EKS.UNIT ON EKS.ITEMDIMENSION.CASEUNITID = EKS.UNIT.UNITID INNER JOIN
EKS.TRANSLATION_INT_UNIT ON EKS.UNIT.SHORTDESCID = EKS.TRANSLATION_INT_UNIT.TRANSLATIONID INNER JOIN
EKS_CALCULATION.EKS_ZSM_ArticleParameter ON (EKS_CALCULATION.stMARA_EKS_ITEM.zNegotiatingCountry = 'US' AND EKS.TRANSLATION_INT_UNIT.DESCRIPTION = 'in' AND EKS_CALCULATION.EKS_ZSM_ArticleParameter.ID = 'RPTDQ025i' OR (EKS_CALCULATION.stMARA_EKS_ITEM.zNegotiatingCountry <> 'US' OR EKS.TRANSLATION_INT_UNIT.DESCRIPTION <> 'in') AND EKS_CALCULATION.EKS_ZSM_ArticleParameter.ID = 'RPTDQ025') AND EKS_CALCULATION.svMARA_EKS_ITEM_Messures_Diff_BETW_Articles010.Volume > EKS_CALCULATION.EKS_ZSM_ArticleParameter.Value INNER JOIN
EKS.SUPPLIER ON EKS.SUPPLIER.SUPPLIERNO = eks.SUPPLIERNO INNER JOIN
EKS.LISTINGOVERVIEW ON EKS.LISTINGOVERVIEW.LISTINGOVERVIEWID = eks.LISTINGOVERVIEWID INNER JOIN
EKS.CONTRACTLINK ON EKS.LISTINGOVERVIEW.LISTINGOVERVIEWID = EKS.CONTRACTLINK.LISTINGOVERVIEWID LEFT OUTER JOIN
EKS.LOHEADING AS LH ON LH.LOHEADINGID = EKS.LISTINGOVERVIEW.LOHEADINGID LEFT OUTER JOIN
EKS.LOCATEGORY AS LC ON LC.LOCATEGORYID = EKS.LISTINGOVERVIEW.LOCATEGORYID LEFT OUTER JOIN
EKS.TRANSLATION_INT AS TR_LC ON TR_LC.TRANSLATIONID = LC.DESCRIPTIONID LEFT OUTER JOIN
EKS.TRANSLATION_INT AS TR_LH ON TR_LH.TRANSLATIONID = LH.DESCRIPTIONID LEFT OUTER JOIN
EKS.CONTRACTSIGNVALUE AS CSV ON CSV.CONTRACTLINKID = EKS.CONTRACTLINK.CONTRACTLINKID AND CSV.SIGNSPECID = 1 LEFT OUTER JOIN
EKS.SIGNSPECVAL AS SP ON SP.SIGNSPECVALID = CSV.SIGNSPECVALID LEFT OUTER JOIN
EKS.TRANSLATION_INT AS TR_SP ON TR_SP.TRANSLATIONID = SP.DESCRIPTIONID LEFT OUTER JOIN
EKS.VALIDITY AS VL ON VL.VALIDITYID = EKS.CONTRACTPRICEVALIDITY.VALIDITYID LEFT OUTER JOIN
EKS.TRANSLATION_INT AS TR_VL ON TR_VL.TRANSLATIONID = VL.DESCRIPTIONID LEFT OUTER JOIN 
EKS_CALCULATION.EKS_ZSM_ExcludeList ON EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO = EKS_CALCULATION.EKS_ZSM_ExcludeList.ITEMNO AND ( ( EKS.SUPPLIER.INTSUPPLIERNO = EKS_CALCULATION.EKS_ZSM_ExcludeList.SUPPLIERNO AND EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID IS NULL ) OR ( eks.LISTINGOVERVIEWID = EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID AND EKS_CALCULATION.EKS_ZSM_ExcludeList.SupplierNo IS NULL )  OR ( EKS.SUPPLIER.INTSUPPLIERNO = EKS_CALCULATION.EKS_ZSM_ExcludeList.SUPPLIERNO  AND eks.LISTINGOVERVIEWID = EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID ) OR ( EKS_CALCULATION.EKS_ZSM_ExcludeList.SupplierNo IS NULL AND EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID IS NULL ) ) AND EKS_CALCULATION.EKS_ZSM_ExcludeList.REPORTNO = '025'
WHERE  ((CASE WHEN lower(ifnull(TR_LC.DESCRIPTION, 'x')) LIKE '%display%' THEN 1 WHEN lower(ifnull(TR_LH.DESCRIPTION, 'x')) LIKE '%display%' THEN 1 WHEN lower(ifnull(TR_SP.DESCRIPTION, 'x')) LIKE '%display%' THEN 1 WHEN lower(ifnull(TR_VL.DESCRIPTION, 'x')) LIKE '%palette%' THEN 1 ELSE 0 END) = 0) and ( EKS_CALCULATION.EKS_ZSM_ExcludeList.ITEMNO IS NULL ) 
);